public class Main {
    static class Bean { static int cnt = 0; int id = ++cnt; }
    static class ScopeContainer {
        java.util.Map<String, Object> singletons = new java.util.HashMap<>();
        Object getSingleton(String n) { return singletons.computeIfAbsent(n, k -> new Bean()); }
        Object getPrototype(String n) { return new Bean(); }
    }
    public static void main(String[] args) {
        ScopeContainer c = new ScopeContainer();
        Object s1 = c.getSingleton("b"), s2 = c.getSingleton("b");
        Object p1 = c.getPrototype("b"), p2 = c.getPrototype("b");
        System.out.println("singleton same: " + (s1 == s2));
        System.out.println("prototype same: " + (p1 == p2));
        System.out.println("prototype ids: " + ((Bean) p1).id + "," + ((Bean) p2).id);
    }
}
